    97	    return (
    98	        <KYCWall
    99	            onSuccessfulKYC={(paymentType) => onPress(paymentType)}
   100	            enablePaymentsRoute={enablePaymentsRoute}
   101	            addDebitCardRoute={addDebitCardRoute}
   102	            isDisabled={isOffline}
