   106	            anchorAlignment={kycWallAnchorAlignment}
   107	            shouldShowPersonalBankAccountOption={shouldShowPersonalBankAccountOption}
   108	        >
   109	            {(triggerKYCFlow, buttonRef) => (
   110	                <ButtonWithDropdownMenu<PaymentType>
