     9	import SettlementButton from '.';
    10	import type SettlementButtonProps from './types';
    11	
    12	type AnimatedSettlementButtonProps = SettlementButtonProps & {
    13	    isPaidAnimationRunning: boolean;
    14	    onAnimationFinish: () => void;
    15	    isApprovedAnimationRunning: boolean;
    16	    shouldAddTopMargin?: boolean;
    17	    canIOUBePaid: boolean;
    18	};
    19	
    20	function AnimatedSettlementButton({
    21	    isPaidAnimationRunning,
    22	    isApprovedAnimationRunning,
    23	    onAnimationFinish,
    24	    shouldAddTopMargin = false,
    25	    isDisabled,
    26	    canIOUBePaid,
    27	    wrapperStyle,
    28	    ...settlementButtonProps
    29	}: AnimatedSettlementButtonProps) {
    30	    const styles = useThemeStyles();
    31	    const {translate} = useLocalize();
    32	
    33	    const isAnimationRunning = isPaidAnimationRunning || isApprovedAnimationRunning;
    34	    const buttonDuration = isPaidAnimationRunning ? CONST.ANIMATION_PAID_DURATION : CONST.ANIMATION_THUMBS_UP_DURATION;
    35	    const buttonDelay = CONST.ANIMATION_PAID_BUTTON_HIDE_DELAY;
    36	    const gap = styles.expenseAndReportPreviewTextButtonContainer.gap;
    37	    const buttonMarginTop = useSharedValue<number>(gap);
    38	    const height = useSharedValue<number>(variables.componentSizeNormal);
    39	    const [canShow, setCanShow] = React.useState(true);
    40	    const [minWidth, setMinWidth] = React.useState<number>(0);
    41	    const viewRef = useRef<HTMLElement | null>(null);
    42	
    43	    const containerStyles = useAnimatedStyle(() => ({
    44	        height: height.get(),
    45	        justifyContent: 'center',
    46	        ...(shouldAddTopMargin && {marginTop: buttonMarginTop.get()}),
    47	    }));
    48	
    49	    const willShowPaymentButton = canIOUBePaid && isApprovedAnimationRunning;
    50	    const stretchOutY = useCallback(() => {
    51	        'worklet';
    52	
    53	        if (shouldAddTopMargin) {
    54	            buttonMarginTop.set(withTiming(willShowPaymentButton ? gap : 0, {duration: buttonDuration}));
    55	        }
    56	        if (willShowPaymentButton) {
    57	            runOnJS(onAnimationFinish)();
    58	            return;
    59	        }
    60	        height.set(withTiming(0, {duration: buttonDuration}, () => runOnJS(onAnimationFinish)()));
    61	    }, [buttonDuration, buttonMarginTop, gap, height, onAnimationFinish, shouldAddTopMargin, willShowPaymentButton]);
    62	
    63	    const buttonAnimation = useMemo(
    64	        () =>
    65	            new Keyframe({
    66	                from: {
    67	                    opacity: 1,
    68	                    transform: [{scale: 1}],
    69	                },
    70	                to: {
    71	                    opacity: 0,
    72	                    transform: [{scale: 0}],
    73	                },
    74	            })
    75	                .delay(buttonDelay)
    76	                .duration(buttonDuration)
    77	                .withCallback(stretchOutY),
    78	        [buttonDelay, buttonDuration, stretchOutY],
    79	    );
    80	
    81	    let icon;
    82	    if (isApprovedAnimationRunning) {
    83	        icon = Expensicons.ThumbsUp;
    84	    } else if (isPaidAnimationRunning) {
    85	        icon = Expensicons.Checkmark;
    86	    }
    87	
    88	    useEffect(() => {
    89	        if (!isAnimationRunning) {
    90	            setMinWidth(0);
    91	            setCanShow(true);
    92	            height.set(variables.componentSizeNormal);
    93	            buttonMarginTop.set(shouldAddTopMargin ? gap : 0);
    94	            return;
    95	        }
    96	        setMinWidth(viewRef.current?.getBoundingClientRect?.().width ?? 0);
    97	        const timer = setTimeout(() => setCanShow(false), CONST.ANIMATION_PAID_BUTTON_HIDE_DELAY);
    98	        return () => clearTimeout(timer);
    99	    }, [buttonMarginTop, gap, height, isAnimationRunning, shouldAddTopMargin]);
   100	
   101	    return (
   102	        <Animated.View style={[containerStyles, wrapperStyle, {minWidth}]}>
   103	            {isAnimationRunning && canShow && (
   104	                <Animated.View
   105	                    ref={(el) => {
   106	                        viewRef.current = el as HTMLElement | null;
   107	                    }}
   108	                    exiting={buttonAnimation}
   109	                >
   110	                    <Button
   111	                        text={isApprovedAnimationRunning ? translate('iou.approved') : translate('iou.paymentComplete')}
   112	                        success
   113	                        icon={icon}
   114	                    />
   115	                </Animated.View>
   116	            )}
   117	            {!isAnimationRunning && (
   118	                <SettlementButton
   119	                    // eslint-disable-next-line react/jsx-props-no-spreading
   120	                    {...settlementButtonProps}
   121	                    wrapperStyle={wrapperStyle}
   122	                    isDisabled={isAnimationRunning || isDisabled}
   123	                />
   124	            )}
   125	        </Animated.View>
   126	    );
   127	}
