   108	function calculateWalletTransferBalanceFee(currentBalance: number, methodType: string): number {
   109	    const transferMethodTypeFeeStructure =
   110	        methodType === CONST.WALLET.TRANSFER_METHOD_TYPE.INSTANT ? CONST.WALLET.TRANSFER_METHOD_TYPE_FEE.INSTANT : CONST.WALLET.TRANSFER_METHOD_TYPE_FEE.ACH;
